?>
<div class="sl-head"><div><h1 class="sl-title">Integrations</h1><p class="sl-lede"><?= (int) $d['on'] ?> of <?= (int) $d['total'] ?> integrations configured · keys are masked</p></div><div class="row g8 wrap"><a class="sl-btn ghost" href="<?= sl_route('ApiConnections') ?>"><i class="ic ic-sm i-link" aria-hidden="true"></i>API connections</a><a class="sl-btn" href="<?= sl_route('ApiAccess') ?>"><i class="ic ic-sm i-key" aria-hidden="true"></i>API keys</a></div></div>
<div class="dv-tabs"><?php foreach ((array) sl_get($d, 'groups', []) as $g): ?><a class="<?= sl_v($g, 'cls') ?>" href="<?= sl_v($g, 'href') ?>"><?= sl_v($g, 'label') ?></a><?php endforeach; ?></div>
<div class="split"><section class="a sl-card flush"><div class="sl-tw"><table class="sl-table"><thead><tr><th>Integration</th><th>Group</th><th>Status</th><th>Settings</th><th>Use (7 d)</th><th></th></tr></thead><tbody><?php foreach ((array) sl_get($d, 'rows', []) as $r): ?><tr><td><div class="sl-cell"><span class="ni sl-tile"><i class="ic <?= h($r['icon']) ?>" aria-hidden="true"></i></span><span class="fw5"><?= h($r['name']) ?></span></div></td><td class="sm"><?= h($r['group']) ?></td><td><span class="lgd"><i style="background:<?= $r['configured'] ? '#3FD08F' : '#8E8A82' ?>"></i><?= $r['configured'] ? 'Configured' : 'Not set up' ?></span></td><td class="mono sm"><?= h($r['detail']) ?></td><td class="sm <?= !empty($r['failed7']) ? 'dv-warn' : '' ?>"><?= h($r['usage'] ?: '—') ?></td><td><a class="sl-btn ghost sm" href="<?= h($r['href']) ?>">Settings</a></td></tr><?php endforeach; ?></tbody></table></div></section>
<aside class="b col g16"><section class="sl-card col g8"><h2 class="sl-ct">Messages · 24 h</h2><?php foreach ((array) $d['channels'] as $ch => $c): ?><div class="dv-row"><span class="grow"><?= h(ucfirst($ch)) ?></span><span class="mono sm"><?= (int) $c['sent'] ?> sent · <span class="<?= $c['failed'] ? 'dv-warn' : '' ?>"><?= (int) $c['failed'] ?> failed</span></span></div><?php endforeach; ?><?php if (!$d['channels']): ?><span class="mut sm">Nothing sent in 24 hours.</span><?php endif; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">API tokens</h2><?php foreach ((array) $d['tokens'] as $t): ?><div class="dv-row"><span class="grow"><?= h(($t->name ?: 'token') . ' · ' . trim((string) $t->who)) ?></span><span class="mut sm"><?= $t->last_used_at ? 'used ' . h(sl_ago($t->last_used_at)) : 'never used' ?></span></div><?php endforeach; ?><?php if (!$d['tokens']): ?><span class="mut sm">No active tokens.</span><?php endif; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">Inbound webhooks</h2><?php foreach ((array) $d['webhooks'] as $w): ?><div class="dv-row"><span class="mono sm grow" style="word-break:break-all"><?= h($w->p) ?></span><span class="mut sm"><?= h(sl_ago($w->created_at)) ?></span></div><?php endforeach; ?><?php if (!$d['webhooks']): ?><span class="mut sm">None received.</span><?php endif; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">CORS origins</h2><?php foreach ((array) $d['cors'] as $c): ?><div class="dv-row"><span class="mono sm grow"><?= h($c->origin) ?></span><span class="mut sm"><?= (int) $c->active ? 'active' : 'off' ?></span></div><?php endforeach; ?><?php if (!$d['cors']): ?><span class="mut sm">No origins listed · config allows <?= h(defined('CDP_API_ALLOWED_ORIGINS') ? (string) CDP_API_ALLOWED_ORIGINS : 'none') ?></span><?php endif; ?></section></aside></div>
